import sys
from collections import deque

def solve():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])

    grid = [list(row) for row in data[2:2+N]]

    queue = deque()

    for r in range(N):
        for c in range(M):
            if grid[r][c] == 'o':
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()

        # Rule 1: downwards
        if r + 1 < N and grid[r + 1][c] == '.':
            grid[r + 1][c] = 'o'
            queue.append((r + 1, c))

        # Rules 2 and 3: sideways if shelf directly below
        if r + 1 < N and grid[r + 1][c] == '#':
            # to the left
            if c - 1 >= 0 and grid[r][c - 1] == '.':
                grid[r][c - 1] = 'o'
                queue.append((r, c - 1))
            # to the right
            if c + 1 < M and grid[r][c + 1] == '.':
                grid[r][c + 1] = 'o'
                queue.append((r, c + 1))

    output = [''.join(row) for row in grid]
    sys.stdout.write('\n'.join(output) + '\n')

if __name__ == '__main__':
    solve()
